output-contract.example:
{
  "feature_id": "F021",
  "path": "features/in-progress/F021-upgrade-page/user-flows.md",
  "flows": [
    {
      "id": "F-01",
      "title": "Signed-in user upgrades to solo tier",
      "actor": "signed-in free-tier user with verified email",
      "preconditions": ["account exists", "Stripe customer record exists", "no active subscription"],
      "happy_path": [
        {"action": "Click \"Upgrade\" in nav", "expected": "routed to /upgrade"},
        {"action": "Select \"Solo $19/mo\"", "expected": "Stripe Elements form appears"},
        {"action": "Enter test card 4242 4242 4242 4242, submit", "expected": "request sent"},
        {"action": "Wait for response", "expected": "200 redirect to /account?upgraded=solo; success toast; tier=solo in /api/account"}
      ],
      "negative_paths": [
        {"name": "Card declined (test card 4000 0000 0000 0002)", "trigger": "submit declined card", "expected_ux": "inline error under card field \"Your card was declined.\", form stays editable, no charge created"},
        {"name": "Network drop mid-submit", "trigger": "throttle network to offline after click submit", "expected_ux": "spinner times out at 30s, toast \"Connection lost. Try again.\" NO partial subscription"}
      ],
      "playwright_spec": "faion-net-e2e/tests/upgrade.spec.ts"
    }
  ]
}
